const http = (options) => this.helpers.httpRequest(options);

async function serviceToken() {
  const body = `grant_type=client_credentials&client_id=salon-agent&client_secret=${encodeURIComponent($env.SALON_AGENT_SECRET)}`;
  const { access_token } = await http({
    method: 'POST',
    url: $env.KEYCLOAK_TOKEN_URL,
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body,
    json: true,
  });
  return access_token;
}

async function graphql(url, token, query, variables = {}) {
  const response = await http({
    method: 'POST',
    url,
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: { query, variables },
    json: true,
  });
  if (response.errors?.length) throw new Error(response.errors[0].message);
  return response.data;
}

// Se envía solo con WhatsApp configurado, con teléfono y con la autorización del cliente
function whatsappItem(phone, text, template, parameters = []) {
  const to = String(phone ?? '').replace(/\D/g, '');
  if (!$env.WHATSAPP_TOKEN || !to) return [];
  // Meta solo admite texto libre dentro de una conversación abierta: lo demás requiere una plantilla aprobada
  const message = template
    ? { type: 'template', template: { name: template, language: { code: 'es' }, components: [{ type: 'body', parameters: parameters.map((value) => ({ type: 'text', text: String(value) })) }] } }
    : { type: 'text', text: { body: text } };
  return [{ json: { payload: { messaging_product: 'whatsapp', to, ...message } } }];
}

async function clientContact(token, clientId) {
  const { getClientById } = await graphql($env.CRM_GRAPHQL_URL, token, 'query ($id: ID!) { getClientById(id: $id) { fullName phone whatsappOptIn } }', { id: clientId });
  return getClientById;
}

const incoming = $input.first().json.body?.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
// Meta también avisa de entregas y lecturas: solo se responde a los mensajes de texto
if (incoming?.type !== 'text') return [];
const text = incoming.text.body.trim().toLowerCase();

if (text === '1') return whatsappItem(incoming.from, '¡Gracias! Te esperamos en tu cita.');
if (text === '2') return whatsappItem(incoming.from, `Puedes reprogramar tu cita en "Mis citas": ${$env.PORTAL_URL}`);
if (!/reserv|cita|turno|precio|servicio/.test(text)) {
  return whatsappItem(incoming.from, 'Hola, soy el asistente del salón. Escribe "reservar" para ver nuestros servicios.');
}
const { getServices } = await graphql($env.GESTION_GRAPHQL_URL, await serviceToken(), '{ getServices { name price durationMinutes } }');
const list = getServices.map(({ name, price, durationMinutes }) => `- ${name}: $${price.toFixed(2)} (${durationMinutes} min)`).join('\n');
return whatsappItem(incoming.from, `Nuestros servicios:\n${list}\n\nReserva y paga tu cita en ${$env.PORTAL_URL}`);

const { query } = $input.first().json;
if (!$env.WHATSAPP_VERIFY_TOKEN || query['hub.verify_token'] !== $env.WHATSAPP_VERIFY_TOKEN) throw new Error('Token de verificación incorrecto.');
return [{ json: { challenge: query['hub.challenge'] } }];

// Meta firma cada aviso con la clave secreta de la app (X-Hub-Signature-256): lo que no esté firmado no se procesa.
// Sin clave configurada (desarrollo local con la API simulada) se acepta como antes; en producción debe estar definida.
const secret = $env.WHATSAPP_APP_SECRET;
if (!secret) return $input.all();

const crypto = require('crypto');
const item = $input.first();
const header = String(item.json.headers?.['x-hub-signature-256'] ?? '');
let raw;
try {
  raw = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (error) {
  throw new Error('El aviso llegó sin cuerpo: se descarta.');
}
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');
const received = Buffer.from(header);
const valid = Buffer.from(expected);
// Comparación en tiempo constante: no revela cuántos caracteres coinciden
if (received.length !== valid.length || !crypto.timingSafeEqual(received, valid)) {
  throw new Error('Firma de Meta inválida: el aviso se descarta.');
}
return $input.all();
